#include <stdio.h>

int main() {
    /* 指令字长 16 位，4 个地址字段各 4 位，每段扩展保留全 1 码点 */
    printf("扩展操作码（4位一段）方案：\n");
    printf("三地址指令：%d 条（0000~1110，1111 保留扩展）\n", 15);
    printf("二地址指令：%d 条（1111 0000~1111 1110）\n", 15);
    printf("一地址指令：%d 条（1111 1111 0000~1111 1111 1110）\n", 15);
    printf("零地址指令：%d 条（1111 1111 1111 0000~1111 1111 1111 1111）\n", 16);
    int total = 15 + 15 + 15 + 16;
    printf("总计可表示指令种类 = %d 条\n", total);
    return 0;
}
